    h.request("ui.text", json!({"text": "zz-no-such-photo"}), t);
    h.settle(SETTLE);
    assert_eq!(h.app.ui.search, "zz-no-such-photo");
    assert!(h.app.session.visible_cloned().is_empty());
}

